  const timeParts = cleanTime.split(":").map((n) => parseInt(n, 10));
  const hh = clampNum(Number.isFinite(timeParts[0]) ? timeParts[0] : 17, 0, 23);
  const mm = clampNum(Number.isFinite(timeParts[1]) ? timeParts[1] : 0, 0, 59);
  const hourFloat = hh + mm / 60;

  const curM = climate.months[mIdx];
  const neighborIdx = day < 15 ? (mIdx + 11) % 12 : (mIdx + 1) % 12;
  const neighborM = climate.months[neighborIdx];
  const blend = day < 15 ? (15 - day) / 30 : day > 15 ? (day - 15) / 30 : 0;
  const lerp = (a: number, b: number) => a + (b - a) * blend;

  const tDay = lerp(curM.tDay, neighborM.tDay);
  const tNight = lerp(curM.tNight, neighborM.tNight);
  const tMax = lerp(curM.tMax ?? curM.tDay + 9, neighborM.tMax ?? neighborM.tDay + 9);
  const tMin = lerp(curM.tMin ?? curM.tNight - 13, neighborM.tMin ?? neighborM.tNight - 13);
  const precipProb = lerp(curM.precipProb ?? 0.45, neighborM.precipProb ?? 0.45);
  const snowProb = lerp(curM.snowProb ?? 0, neighborM.snowProb ?? 0);
  const avgWind = lerp(curM.avgWind ?? 3.2, neighborM.avgWind ?? 3.2);
  const baseHumidity = lerp(curM.humidity ?? 75, neighborM.humidity ?? 75);

  const dayRand = weatherPrng(hashWeatherSeed(`${city.toLowerCase()}|${cleanDate}`));
  const timeRand = weatherPrng(hashWeatherSeed(`${city.toLowerCase()}|${cleanDate}|${cleanTime}`));

  const diurnal = 0.5 + 0.5 * Math.cos(((hourFloat - 14.5) / 24) * 2 * Math.PI);
  const baseTemp = tNight + (tDay - tNight) * diurnal;
  const synopticAnomaly = (dayRand() + dayRand() - 1) * 4.8;
  const microTemp = (timeRand() - 0.5) * 1.0;
  let temp = Math.round(clampNum(baseTemp + synopticAnomaly + microTemp, tMin, tMax));
