  const windFactor = 0.65 + dayRand() * 0.8 + (timeRand() - 0.5) * 0.14;
  const windDirRoll = dayRand();
  const windDirIdxRoll = Math.floor(dayRand() * WIND_DIRS_8.length);
  const pressureOffset = Math.round((dayRand() + dayRand() - 1) * 9);
  const humidityOffset = Math.round((dayRand() + dayRand() - 1) * 11 + (timeRand() - 0.5) * 4);

  const wind = Math.max(0.5, round1(avgWind * windFactor));
