  db.interviewUsage ||= {};
  db.interviewUsage[f.id] ||= {};
  const usageRec = db.interviewUsage[f.id][actor.actorKey] || { count: 0, items: [] };
  const usedBefore = Number(usageRec.count || 0);
  if (usedBefore >= INTERVIEW_Q_LIMIT) {
    return fail(res, `Вы уже задали максимальное количество вопросов лучшему игроку этого матча (${INTERVIEW_Q_LIMIT}/${INTERVIEW_Q_LIMIT}).`, 400);
  }

  // 1. Сначала обязательная проверка и списание просмотренной рекламы Adsgram
  const adCheck = verifyAndConsumeAdProof(req.body?.adProof, "interview_ask", actor.actorKey, false);
  if (!adCheck.ok) {
    return fail(res, adCheck.error, 400);
  }

  // 2. И только после просмотра рекламы — проверка корректности вопроса
  const qCheck = validateInterviewQuestion(req.body?.question);
  if (!qCheck.ok) {
    return fail(res, qCheck.error, 400);
  }
  const question = qCheck.question;

  const resolvedTid = motm.teamId || motm.player?.teamId || (motm.side === "away" ? f.away : f.home);
  const isHome = resolvedTid === f.home;
  const sideCoach = isHome ? cH : cA;
  const myTeamName = motm.teamName || motm.team || (isHome ? HName : AName);
  const oppTeamName = isHome ? AName : HName;
